using System;
using System.Collections;
using System.IO;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.Rendering;
namespace NexoAvance {
public class ActionCheck:MonoBehaviour {
 const string Out="C:/Users/jose/Documents/Codex/2026-09-22/ho/outputs/Acciones/";bool failed;float began;int checks;ResistancePlayer p;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Boot(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-actionCheck")<0)return;var go=new GameObject("Validación acciones");DontDestroyOnLoad(go);go.AddComponent<ActionCheck>();}
 void Check(bool ok,string label){checks++;failed|=!ok;File.AppendAllText(Out+"validacion.txt",(ok?"OK ":"ERROR ")+label+"\n");}
 void Update(){if(Time.realtimeSinceStartup-began>500){File.AppendAllText(Out+"validacion.txt","ERROR tiempo agotado\n");Application.Quit(2);}}
 void Place(Vector2 v){p.transform.position=v;p.GetComponent<Rigidbody2D>().position=v;p.GetComponent<Rigidbody2D>().linearVelocity=Vector2.zero;Physics2D.SyncTransforms();}
 CombatHealth Target(float x){var go=new GameObject("Diana");go.transform.position=new Vector2(x,-.12f);go.AddComponent<BoxCollider2D>().size=new Vector2(.3f,1.6f);var h=go.AddComponent<CombatHealth>();h.team=CombatTeam.Robot;Physics2D.SyncTransforms();return h;}
 void Capture(string name){Canvas.ForceUpdateCanvases();var rt=new RenderTexture(1280,720,24);rt.Create();RenderPipeline.SubmitRenderRequest(Camera.main,new RenderPipeline.StandardRequest{destination=rt});var old=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(1280,720,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1280,720),0,0);t.Apply();File.WriteAllBytes(Out+name,t.EncodeToPNG());RenderTexture.active=old;rt.Release();Destroy(rt);Destroy(t);}
 IEnumerator Start(){began=Time.realtimeSinceStartup;Application.runInBackground=true;Application.targetFrameRate=60;QualitySettings.vSyncCount=0;File.WriteAllText(Out+"validacion.txt","");bool only=Array.IndexOf(Environment.GetCommandLineArgs(),"-asaltoOnly")>=0;
  for(int hero=0;hero<(only?1:4);hero++)for(int m=0;m<(only?1:3);m++){
   HeroSelection.Choose(hero);Time.timeScale=1;yield return SceneManager.LoadSceneAsync(new[]{"CallesBajoControl","FabricaAutomatizada","NucleoNexo"}[m]);yield return null;var d=FindAnyObjectByType<EncounterDirector>();d.enabled=false;p=d.session.player;p.TestMode=true;p.SetPaused(false);var gun=p.GetComponent<PlayerCombat>();var action=p.GetComponent<PlayerActions>();var look=p.GetComponent<HeroAppearance>();var hp=d.session.health;string tag="H"+hero+" M"+(m+1)+" ";Place(new Vector2(1,-.12f));yield return new WaitForSeconds(.3f);
   var design=look.roster.heroes[hero];Check(design.animations.run.Length==6&&design.animations.meleeImpact.Length>0&&design.animations.grenade.Length>0&&design.animations.death.Length>0,tag+"clips reales asignados");if(m==0)Capture("Heroe-"+hero+"-reposo.png");
   p.TestAxis=1;var sprites=new HashSet<Sprite>();gun.TestFire=true;float until=Time.time+.5f;while(Time.time<until){sprites.Add(p.visual.sprite);yield return null;}gun.TestFire=false;p.TestAxis=0;Check(sprites.Count>=3,tag+"carrera y disparo no congelan las piernas");Check(p.visual.transform.localScale==Vector3.one,tag+"sin deformación global");CombatBullet.ClearAll();Place(new Vector2(1,-.12f));yield return new WaitForSeconds(.2f);
   p.TestJump=true;yield return new WaitForSeconds(.25f);Check(p.Velocity.y>0&&!p.AirJumpUsed,tag+"salto inicial");p.TestJump=true;yield return new WaitForSeconds(.1f);Check(p.AirJumpUsed&&p.Velocity.y>5,tag+"segundo impulso requiere nueva pulsación");float v=p.Velocity.y;p.TestJump=true;yield return new WaitForSeconds(.1f);Check(p.Velocity.y<v,tag+"tercer salto rechazado");bool fired=gun.TryShoot();Check(fired,tag+"disparo aéreo");if(m==0)Capture("Heroe-"+hero+"-salto.png");yield return new WaitForSeconds(1.2f);Check(p.Grounded&&!p.AirJumpUsed,tag+"aterrizaje restablece salto");
   Place(new Vector2(1,4));yield return new WaitForSeconds(.15f);p.TestJump=true;yield return new WaitForSeconds(.1f);yield return new WaitForFixedUpdate();yield return null;Check(p.AirJumpUsed,tag+"caer sin saltar consume único salto aéreo");Place(new Vector2(1,-.12f));yield return new WaitForSeconds(.3f);CombatBullet.ClearAll();p.visual.flipX=false;
   Place(new Vector2(1,4));yield return new WaitForFixedUpdate();p.TestJump=true;yield return new WaitForSeconds(.06f);yield return new WaitForFixedUpdate();yield return null;Check(p.AirJumpUsed,tag+"salto tras salir del borde consume impulso aéreo");Place(new Vector2(1,-.12f));yield return new WaitForSeconds(.3f);var target=Target(2);int before=target.Current;Check(action.TryMelee()&&!action.TryMelee(),tag+"golpe y bloqueo de repetición");yield return new WaitForSeconds(.05f);Check(target.Current==before,tag+"preparación sin daño");yield return new WaitForSeconds(.075f);if(m==0)Capture("Heroe-"+hero+"-golpe.png");yield return new WaitForSeconds(.125f);Check(target.Current==before-gun.damage*2,tag+"impacto único equivale a dos balas");yield return new WaitForSeconds(.3f);Check(!action.Busy&&target.Current==before-gun.damage*2,tag+"recuperación libera acciones");
   var wall=new GameObject("Pared de prueba");wall.transform.position=new Vector2(1.5f,0);wall.AddComponent<BoxCollider2D>().size=new Vector2(.1f,3);Physics2D.SyncTransforms();before=target.Current;action.TryMelee();yield return new WaitForSeconds(.5f);Check(target.Current==before,tag+"pared bloquea golpe");Destroy(wall);Destroy(target.gameObject);yield return null;
   var left=Target(0);var right=Target(2);p.visual.flipX=true;action.TryMelee();yield return new WaitForSeconds(.5f);Check(left.Current==100-gun.damage*2&&right.Current==100,tag+"golpe izquierdo solo daña delante");Destroy(left.gameObject);Destroy(right.gameObject);p.visual.flipX=false;hp.invulnerability=0;hp.Hit(1,CombatTeam.Robot);yield return null;Check(look.State==HeroMotion.Hurt,tag+"reacción de daño");yield return new WaitForSeconds(.3f);Check(look.State!=HeroMotion.Hurt,tag+"daño libera estado");
   var inventory=p.GetComponent<GrenadeInventory>();inventory.Give(1);int count=inventory.Count;Check(inventory.TryThrow()&&inventory.Count==count-1&&!inventory.TryThrow(),tag+"una granada por acción");yield return new WaitForSeconds(.3f);inventory.ClearThrows();
   var victim=Target(2);action.TryMelee();hp.invulnerability=0;hp.Hit(10000,CombatTeam.Robot);yield return new WaitForSecondsRealtime(.3f);if(m==0)Capture("Heroe-"+hero+"-derrota.png");Check(!action.TryMelee()&&!gun.TryShoot()&&victim.Current==100,tag+"muerte interrumpe golpe pendiente");d.session.Restart();yield return null;Check(hp.Alive&&!action.Busy&&!p.AirJumpUsed&&look.AppliedIndex==hero,tag+"reaparición limpia estados y conserva héroe");
  }
  File.AppendAllText(Out+"validacion.txt","RESULTADO: "+(failed?"ERROR":"CORRECTO")+" · "+checks+" comprobaciones\n");Application.Quit(failed?1:0);
 }
}
}
